use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process;
use walkdir::WalkDir;
use chrono::DateTime;
use chrono::Local;
use serde_json::json;

mod parser;
mod evaluator;
mod formatter;

use parser::{Query, parse_query};
use evaluator::evaluate_file;
use formatter::format_output;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        print_help();
        process::exit(0);
    }

    // Check for help or version flags
    if args[1] == "--help" || args[1] == "-h" {
        print_help();
        process::exit(0);
    }

    if args[1] == "--version" || args[1] == "-v" {
        print_version();
        process::exit(0);
    }

    // Join all arguments into a single query string
    let query_str = args[1..].join(" ");

    match parse_query(&query_str) {
        Ok(query) => {
            execute_query(&query);
        }
        Err(e) => {
            eprintln!("\x1b[33mquery\x1b[0m: {}", e);
            process::exit(2);
        }
    }
}

fn execute_query(query: &Query) {
    let mut results = Vec::new();

    // Get search roots
    let roots = if query.from_paths.is_empty() {
        vec![PathBuf::from(".")]
    } else {
        query.from_paths.clone()
    };

    // Search files
    for root in roots {
        let walker = WalkDir::new(&root)
            .into_iter()
            .filter_map(Result::ok);

        for entry in walker {
            let path = entry.path();

            // Evaluate conditions
            if let Some(ref condition) = query.where_clause {
                if !evaluate_file(path, condition) {
                    continue;
                }
            }

            // Collect row data
            let mut row = Vec::new();
            for column in &query.columns {
                let value = evaluate_file_column(path, column);
                row.push(value);
            }
            results.push(row);
        }
    }

    // Apply limit and offset
    if let Some(offset) = query.offset {
        if offset < results.len() {
            results = results[offset..].to_vec();
        } else {
            results.clear();
        }
    }

    if let Some(limit) = query.limit {
        results.truncate(limit);
    }

    // Format output
    println!("{}", format_output(&results, &query.format));
}

fn evaluate_file_column(path: &Path, column: &str) -> String {
    match column {
        "name" => path.file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("")
            .to_string(),
        "path" => path.to_string_lossy().to_string(),
        "size" => {
            if let Ok(metadata) = fs::metadata(path) {
                metadata.len().to_string()
            } else {
                "0".to_string()
            }
        }
        "is_file" => {
            if let Ok(metadata) = fs::metadata(path) {
                metadata.is_file().to_string()
            } else {
                "false".to_string()
            }
        }
        "is_dir" => {
            if let Ok(metadata) = fs::metadata(path) {
                metadata.is_dir().to_string()
            } else {
                "false".to_string()
            }
        }
        "ext" | "extension" => {
            path.extension()
                .and_then(|e| e.to_str())
                .unwrap_or("")
                .to_string()
        }
        "modified" => {
            if let Ok(metadata) = fs::metadata(path) {
                if let Ok(modified) = metadata.modified() {
                    let datetime: DateTime<Local> = modified.into();
                    datetime.format("%Y-%m-%d %H:%M:%S").to_string()
                } else {
                    String::new()
                }
            } else {
                String::new()
            }
        }
        _ => String::new(),
    }
}

fn print_help() {
    println!("fselect 0.10.0");
    println!("Find files with SQL-like queries.");
    println!("\x1b[4;36mhttps://github.com/jhspetersson/fselect\x1b[0m");
    println!();
    println!("Usage: fselect [ARGS] COLUMN[, COLUMN...] [from PATH[, PATH...]] [where EXPR] [group by COLUMN, ...] [order by COLUMN (asc|desc), ...] [limit N] [offset N] [into FORMAT]");
    // ... more help text
}

fn print_version() {
    println!("fselect \x1b[33m0.10.0\x1b[0m");
    println!("Find files with SQL-like queries.");
    println!("\x1b[4;36mhttps://github.com/jhspetersson/fselect\x1b[0m");
}
EOF

