                i += 1;
                let mut expr = String::new();
                while i < tokens.len() && !is_keyword(&tokens[i]) {
                    if !expr.is_empty() {
                        expr.push(' ');
                    }
                    expr.push_str(&tokens[i]);
                    i += 1;
                }
                where_clause = Some(expr);
            }
            "group" => {
                i += 1;
                if i < tokens.len() && tokens[i].to_lowercase() == "by" {
                    i += 1;
                    let mut cols = String::new();
                    while i < tokens.len() && !is_keyword(&tokens[i]) {
                        if !cols.is_empty() {
                            cols.push(' ');
                        }
                        cols.push_str(&tokens[i]);
                        i += 1;
                    }
                    group_by = parse_columns(&cols);
                }
            }
            "order" => {
                i += 1;
                if i < tokens.len() && tokens[i].to_lowercase() == "by" {
                    i += 1;
                    let mut cols = String::new();
                    while i < tokens.len() && !is_keyword(&tokens[i]) {
                        if !cols.is_empty() {
                            cols.push(' ');
                        }
                        cols.push_str(&tokens[i]);
                        i += 1;
                    }
                    order_by = parse_order_by(&cols);
                }
            }
            "limit" => {
                i += 1;
                if i < tokens.len() {
                    if let Ok(n) = tokens[i].parse::<usize>() {
                        limit = Some(n);
                    }
                    i += 1;
                }
            }
            "offset" => {
                i += 1;
                if i < tokens.len() {
                    if let Ok(n) = tokens[i].parse::<usize>() {
                        offset = Some(n);
                    }
                    i += 1;
                }
            }
            "into" => {
                i += 1;
                if i < tokens.len() {
                    format = tokens[i].to_lowercase();
                    i += 1;
                }
            }
            _ => {
                i += 1;
            }
        }
    }

    Ok(Query {
        columns,
        from_paths,
        where_clause,
        group_by,
        order_by,
        limit,
        offset,
        format,
    })
}

fn tokenize(s: &str) -> Vec<String> {
    let mut tokens = Vec::new();
    let mut current = String::new();
    let mut in_quotes = false;

    for c in s.chars() {
        match c {
            '"' => {
                in_quotes = !in_quotes;
            }
            ' ' | '\t' if !in_quotes => {
                if !current.is_empty() {
                    tokens.push(current.clone());
                    current.clear();
                }
            }
            ',' if !in_quotes => {
                if !current.is_empty() {
                    tokens.push(current.clone());
                    current.clear();
                }
                tokens.push(",".to_string());
            }
            _ => {
                current.push(c);
            }
        }
    }

    if !current.is_empty() {
        tokens.push(current);
    }

    tokens
}

fn is_keyword(s: &str) -> bool {
    let lower = s.to_lowercase();
    matches!(lower.as_str(), 
        "from" | "where" | "group" | "order" | "limit" | "offset" | "into" | "by" | "asc" | "desc")
}

fn parse_columns(s: &str) -> Vec<String> {
    s.split(',')
        .map(|c| c.trim().to_string())
        .filter(|c| !c.is_empty())
        .collect()
}

fn parse_paths(s: &str) -> Vec<PathBuf> {
    s.split(',')
        .map(|p| PathBuf::from(p.trim()))
        .collect()
}

fn parse_order_by(s: &str) -> Vec<(String, bool)> {
    let mut result = Vec::new();
    let parts: Vec<&str> = s.split(',').collect();

    for part in parts {
        let tokens: Vec<&str> = part.split_whitespace().collect();
        if tokens.is_empty() {
            continue;
        }

        let col = tokens[0].to_string();
        let is_asc = if tokens.len() > 1 {
            tokens[1].to_lowercase() != "desc"
        } else {
            true
        };

        result.push((col, is_asc));
    }

    result
}
