        return if let Ok(metadata) = fs::metadata(path) {
            metadata.is_file()
        } else {
            false
        };
    }

    if condition == "is_dir" {
        return if let Ok(metadata) = fs::metadata(path) {
            metadata.is_dir()
        } else {
            false
        };
    }

    // More complex conditions can be added here
    true
}
