use serde_json::json;

pub fn format_output(results: &[Vec<String>], format: &str) -> String {
    match format {
        "json" => format_json(results),
        "csv" => format_csv(results),
        "lines" => format_lines(results),
        "list" => format_list(results),
        "tabs" | _ => format_tabs(results),
    }
}

fn format_tabs(results: &[Vec<String>]) -> String {
    results.iter()
        .map(|row| row.join("\t"))
        .collect::<Vec<_>>()
        .join("\n")
}

fn format_csv(results: &[Vec<String>]) -> String {
    results.iter()
        .map(|row| row.join(","))
        .collect::<Vec<_>>()
        .join("\n")
}

fn format_lines(results: &[Vec<String>]) -> String {
    let mut output = Vec::new();
    for row in results {
        for cell in row {
            output.push(cell.clone());
        }
    }
    output.join("\n")
}

fn format_list(results: &[Vec<String>]) -> String {
    let mut output = Vec::new();
    for row in results {
        for cell in row {
            output.push(cell.clone());
        }
    }
    output.join(" ") + " "
}

fn format_json(results: &[Vec<String>]) -> String {
    let items: Vec<_> = results.iter().map(|row| {
        // Assuming first column is the "Name"
        if row.is_empty() {
            json!({})
        } else {
            json!({ "Name": row[0] })
        }
    }).collect();

    serde_json::to_string(&items).unwrap_or_default()
}

fn format_html(results: &[Vec<String>]) -> String {
    let mut html = String::from("<table>\n");
    for row in results {
        html.push_str("<tr>");
        for cell in row {
            html.push_str("<td>");
            html.push_str(&cell);
            html.push_str("</td>");
        }
        html.push_str("</tr>\n");
    }
    html.push_str("</table>");
    html
}
