use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process;
use std::time::SystemTime;

mod parser;
mod evaluator;
mod formatter;

use parser::{Query, parse_query};
use evaluator::evaluate_file;
use formatter::format_output;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        print_help();
        process::exit(0);
    }

    // Check for help or version flags
    if args[1] == "--help" || args[1] == "-h" {
        print_help();
        process::exit(0);
    }

    if args[1] == "--version" || args[1] == "-v" {
        print_version();
        process::exit(0);
    }

    // Join all arguments into a single query string
    let query_str = args[1..].join(" ");

    match parse_query(&query_str) {
        Ok(query) => {
            execute_query(&query);
        }
        Err(e) => {
            eprintln!("\x1b[33mquery\x1b[0m: {}", e);
            process::exit(2);
        }
    }
}

fn execute_query(query: &Query) {
    let mut results = Vec::new();

    // Get search roots
    let roots = if query.from_paths.is_empty() {
        vec![PathBuf::from(".")]
    } else {
        query.from_paths.clone()
    };

    // Search files
    for root in roots {
        walk_directory(&root, &mut results, &query);
    }

    // Apply offset and limit
    if let Some(offset) = query.offset {
        if offset < results.len() {
            results = results[offset..].to_vec();
        } else {
            results.clear();
        }
    }

    if let Some(limit) = query.limit {
        results.truncate(limit);
    }

    // Format output
    println!("{}", format_output(&results, &query.format));
}

fn walk_directory(path: &Path, results: &mut Vec<Vec<String>>, query: &Query) {
    if let Ok(entries) = fs::read_dir(path) {
        for entry in entries {
            if let Ok(entry) = entry {
                let path = entry.path();

                // Evaluate conditions
                if let Some(ref condition) = query.where_clause {
                    if !evaluate_file(&path, condition) {
                        continue;
                    }
                }

                // Collect row data
                let mut row = Vec::new();
                for column in &query.columns {
                    let value = evaluate_file_column(&path, column);
                    row.push(value);
                }
                results.push(row);

                // Recurse for directories
                if path.is_dir() {
                    walk_directory(&path, results, query);
                }
            }
        }
    }
}

fn evaluate_file_column(path: &Path, column: &str) -> String {
    match column {
        "name" => path.file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("")
            .to_string(),
        "path" | "abspath" => path.to_string_lossy().to_string(),
        "size" => {
            if let Ok(metadata) = fs::metadata(path) {
                metadata.len().to_string()
            } else {
                "0".to_string()
            }
        }
        "is_file" => {
            if let Ok(metadata) = fs::metadata(path) {
                metadata.is_file().to_string()
            } else {
                "false".to_string()
            }
        }
        "is_dir" => {
            if let Ok(metadata) = fs::metadata(path) {
                metadata.is_dir().to_string()
            } else {
                "false".to_string()
            }
        }
        "ext" | "extension" => {
            path.extension()
                .and_then(|e| e.to_str())
                .unwrap_or("")
                .to_string()
        }
        "filename" | "fname" => {
            path.file_stem()
                .and_then(|n| n.to_str())
                .unwrap_or("")
                .to_string()
        }
        "modified" => {
            if let Ok(metadata) = fs::metadata(path) {
                if let Ok(modified) = metadata.modified() {
                    format_system_time(modified)
                } else {
                    String::new()
                }
            } else {
                String::new()
            }
        }
        _ => String::new(),
    }
}

fn format_system_time(time: SystemTime) -> String {
    let duration = time
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap_or_default();

    // Simple timestamp formatting (YYYY-MM-DD HH:MM:SS)
    // Using a basic calculation from seconds since epoch
    let seconds = duration.as_secs();
    let (year, month, day, hour, minute, second) = unix_timestamp_to_datetime(seconds);
    format!("{:04}-{:02}-{:02} {:02}:{:02}:{:02}", year, month, day, hour, minute, second)
}

fn unix_timestamp_to_datetime(timestamp: u64) -> (u32, u32, u32, u32, u32, u32) {
    const SECONDS_PER_DAY: u64 = 86400;
    const DAYS_PER_YEAR: u64 = 365;

    let days_since_epoch = timestamp / SECONDS_PER_DAY;
    let seconds_today = timestamp % SECONDS_PER_DAY;

    let hour = (seconds_today / 3600) as u32;
    let minute = ((seconds_today % 3600) / 60) as u32;
    let second = (seconds_today % 60) as u32;

    // Basic approximation for year/month/day from days since 1970-01-01
    let mut year = 1970;
    let mut remaining_days = days_since_epoch as i32;

    loop {
        let days_in_year = if is_leap_year(year) { 366 } else { 365 };
        if remaining_days >= days_in_year {
            remaining_days -= days_in_year;
            year += 1;
        } else {
            break;
        }
    }

    let days_in_months = if is_leap_year(year) {
        [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    } else {
        [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    };

    let mut month = 1;
    let mut day = remaining_days + 1;

    for &days in &days_in_months {
        if day <= days {
            break;
        }
        day -= days;
        month += 1;
    }

    (year as u32, month, day as u32, hour, minute, second)
}

fn is_leap_year(year: i32) -> bool {
    (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)
}

fn print_help() {
    println!("fselect 0.10.0");
    println!("Find files with SQL-like queries.");
    println!("\x1b[4;36mhttps://github.com/jhspetersson/fselect\x1b[0m");
    println!();
