    const SECONDS_PER_DAY: u64 = 86400;

    let days_since_epoch = timestamp / SECONDS_PER_DAY;
    let seconds_today = timestamp % SECONDS_PER_DAY;

    let hour = (seconds_today / 3600) as u32;
    let minute = ((seconds_today % 3600) / 60) as u32;
    let second = (seconds_today % 60) as u32;

    // Basic approximation for year/month/day from days since 1970-01-01
    let mut year = 1970;
    let mut remaining_days = days_since_epoch as i32;

    loop {
        let days_in_year = if is_leap_year(year) { 366 } else { 365 };
        if remaining_days >= days_in_year {
            remaining_days -= days_in_year;
            year += 1;
        } else {
            break;
        }
    }

    let days_in_months = if is_leap_year(year) {
        [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    } else {
        [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    };

    let mut month = 1;
    let mut day = remaining_days + 1;

    for &days in &days_in_months {
        if day <= days {
            break;
        }
        day -= days;
        month += 1;
    }

    (year as u32, month, day as u32, hour, minute, second)
}

fn is_leap_year(year: i32) -> bool {
    (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)
}

